output.sql:
SELECT substr(order_date,1,7) AS month, SUM(paid_sales_cents) AS sales_amount_cents
FROM v_order_economics WHERE order_date BETWEEN '2026-07-01' AND '2026-08-31'
GROUP BY month ORDER BY month;

